// Cloudflare Pages Function: /go/<id>?p=<page>
// Logs the affiliate click to D1 (best-effort) and 302-redirects to the real
// merchant URL from functions/lib/links.json (generated by scripts/build-affiliate-links.mjs).
//
// The redirect NEVER depends on logging: if the D1 binding is missing or the
// insert fails, the visitor is still sent to the merchant. Set up logging with:
//   wrangler d1 create thepriceofgermany-affiliate
//   wrangler d1 execute thepriceofgermany-affiliate --remote --file=./schema.sql
// then bind it as DB on the Pages project (see README / affiliate setup notes).
import links from '../lib/links.json';

const SLUG = /^[a-z0-9][a-z0-9-]{0,80}$/;

export async function onRequestGet(context) {
  const { params, request, env } = context;
  const id = String(params.id || '');
  const dest = links[id];

  if (!dest) {
    return new Response('Unknown affiliate link.', {
      status: 404,
      headers: { 'content-type': 'text/plain; charset=utf-8' },
    });
  }

  try {
    if (env.DB) {
      const url = new URL(request.url);
      let page = url.searchParams.get('p');
      if (!page || !SLUG.test(page)) {
        // Fall back to the referring page's slug if ?p= was stripped.
        const ref = request.headers.get('referer');
        page = ref ? slugFromUrl(ref) : null;
      }
      const country = request.headers.get('cf-ipcountry') || (request.cf && request.cf.country) || null;
      const referer = request.headers.get('referer') || null;
      context.waitUntil(
        env.DB.prepare(
          'INSERT INTO clicks (link_id, page, country, referer) VALUES (?1, ?2, ?3, ?4)'
        ).bind(id, page, country, referer).run().catch(() => {})
      );
    }
  } catch (_) {
    // Never block the redirect on a logging failure.
  }

  return new Response(null, {
    status: 302,
    headers: { location: dest, 'cache-control': 'no-store' },
  });
}

function slugFromUrl(u) {
  try {
    const p = new URL(u).pathname.replace(/^\/+|\/+$/g, '');
    const slug = p === '' ? 'index' : p.split('/').pop().replace(/\.html$/, '');
    return SLUG.test(slug) ? slug : null;
  } catch { return null; }
}
